const input=$json.body??$json;
const s=v=>String(v??'').trim();
const first=(...v)=>v.find(x=>x!==undefined&&x!==null&&x!=='');
const identity=input.identity??{};
const leadId=s(first(input.lead_id,identity.lead_id));
const propertyId=s(first(input.property_id,identity.property_id));
const dealId=s(first(input.deal_id,identity.deal_id));
const id=s(first(dealId,propertyId,leadId));
const requestId=s(input.request_id)||('evidence-confidence:'+(id||'unknown')+':v1');
const packet=input.packet??input;
const evidence=packet.evidence??{};
const sourceMeta=packet.source_metadata??input.source_metadata??{};
const rules={direct_source:0.95,verified_source:0.9,derived_source:0.8,unknown_source:0.5,missing:0};
function score(value,meta){
 if(value===undefined||value===null||value==='')return {score:0,status:'missing',reason:'no_evidence'};
 const m=meta??{};
 if(Number.isFinite(Number(m.confidence)))return {score:Math.max(0,Math.min(1,Number(m.confidence))),status:'provided_confidence',reason:'source_confidence_supplied'};
 const source=s(m.source_type??m.source);
 if(source==='direct'||source==='primary')return {score:rules.direct_source,status:'direct_source',reason:'primary_or_direct_source'};
 if(source==='verified'||source==='verified_source')return {score:rules.verified_source,status:'verified_source',reason:'verified_source'};
 if(source==='derived'||source==='model'||source==='estimated')return {score:rules.derived_source,status:'derived_source',reason:'derived_or_estimated'};
 if(source)return {score:rules.unknown_source,status:'unknown_source',reason:'source_declared_but_unverified'};
 return {score:rules.unknown_source,status:'unknown_source',reason:'source_metadata_missing'};
}
const keys=['valuation','comps','repairs','risk','buyer_demand','exit_strategy'];
const scores={};
for(const k of keys){
 const v=evidence[k];
 const meta=(packet.evidence_metadata?.[k]??input.evidence_metadata?.[k]??(v&&typeof v==='object'&&!Array.isArray(v)?v.metadata:null));
 scores[k]=score(v,meta);
}
const weights={valuation:.25,comps:.2,repairs:.15,risk:.15,buyer_demand:.1,exit_strategy:.15};
let weighted=0,weightTotal=0;
for(const k of keys){weighted+=scores[k].score*weights[k];weightTotal+=weights[k];}
const overall=weightTotal?weighted/weightTotal:0;
const missing=keys.filter(k=>scores[k].score===0);
const low=keys.filter(k=>scores[k].score>0&&scores[k].score<0.7);
const conflicts=keys.filter(k=>evidence[k]?.conflict===true||evidence[k]?.status==='conflict');
const quality=overall>=.85?'high':overall>=.7?'medium':overall>0?'low':'insufficient';
const ready=missing.length===0&&conflicts.length===0&&overall>=.7;
const packetId=s(packet.packet_id)||('underwriting-packet:'+(id||'unknown')+':v1');
return[{json:{ok:true,status:ready?'confidence_ready':missing.length?'confidence_incomplete':conflicts.length?'confidence_conflict':'confidence_low',request_id:requestId,packet_id:packetId,identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null},source_quality:{overall_score:Number(overall.toFixed(4)),quality,weighted_scores:scores,weights,missing,low_confidence:low,conflicts,threshold:.7},policy:{confidence_required_for_mao:true,low_confidence_blocks_mao:true,conflicts_block_mao:true,unknown_sources_do_not_count_as_verified:true},routing:{next_workflow:ready?'wf-109-underwriting-evidence-aggregator':conflicts.length?'human_review':'wf-111-underwriting-evidence-reconciliation',reason:ready?'evidence_confidence_sufficient_for_aggregation':conflicts.length?'evidence_conflict_requires_review':'evidence_quality_or_completeness_requires_reconciliation'},evidence:packet.evidence??{}}}];
